1	<script setup lang="ts">
2	/**
3	 * Plain-text, keyboard-first conversation reader (UX-02). Opening is read-only —
4	 * never marks read.
5	 *
6	 * Visit-scoped message state (active message, expansion, details disclosure,
7	 * scroll anchor) lives inside this mounted reader instance, keyed by
8	 * account+conversation reference and message ID — never by array position. It
9	 * survives J/K round trips and same-reference background replacements within
10	 * the reader session and is released when the reader closes (component
11	 * unmount) or the account changes.
12	 *
13	 * Archive/read controls are shown only when the authoritative capability permits them, and
14	 * Gmail-supplied plain-text limitations are disclosed explicitly (`unsupportedReason`,
15	 * `contextComplete === false`) instead of silently dropping content.
16	 *
17	 * Safety: message content is rendered exclusively through text interpolation
18	 * ({{ }}). No v-html, no markdown/HTML processing, no remote assets anywhere in
19	 * this slice — hostile markup stays literal text. Reply preparation always
20	 * targets the explicitly displayed latest message, never the focused message.
21	 *
22	 * Message commands (N/P/O/Shift+O, details dismissal) are exposed as narrow
23	 * methods for App's single keyboard dispatcher — this component never adds its
24	 * own window listener.
25	 */
26	import { actionLabel } from '../lib/browsing-actions';
27	import { compactDateLabel, fullDateLabel, machineDateTime } from '../lib/browsing-dates';
28	import { messageSnippet } from '../lib/message-snippet';
29	import { bodyNeedsMonospace } from '../lib/message-body-format';
30	import { computed, nextTick, reactive, ref, useId, watch } from 'vue';
31	import HeaderGlyph from './HeaderGlyph.vue';
32	import type { Address, Conversation, ConversationRef, DraftSource, MailError, Message } from '../lib/ipc/client';
33	import type { DetailState } from '../composables/useMailbox';
34	
35	const props = defineProps<{
36	  conversation: Conversation | null;
37	  state: DetailState;
38	  error: MailError | null;
39	  commandInFlight: boolean;
40	  /** The conversation reference the shell currently wants displayed. */
41	  openRef: ConversationRef | null;
42	  /**
43	   * Target identity from the list's own row, shown while the target loads and
44	   * no previous conversation is held. Never message content.
45	   */
46	  loadingIdentity?: { subject: string; sender: string | null; at: string | null } | null;
47	  /** Gmail mode: archive/unarchive controls are hidden, not just disabled. */
48	  readOnly?: boolean;
49	  browsingOnly?: boolean;
50	  navigationUnavailable?: boolean;
51	  showReadControls?: boolean;
52	  /** Nonzero: shared controls dispatch to the SELECTION (§3.3), so the reader
53	   * offers explicit count-labelled desired-state controls instead of the open
54	   * conversation's single-state toggles (mixed selections included). */
55	  selectionCount?: number;
56	  selectionContext?: 'inbox' | 'saved' | 'done' | 'starred' | 'search';
57	  /** Header slots the quiet icon actions are teleported into; inline when null. */
58	  backHost?: HTMLElement | null;
59	  actionsHost?: HTMLElement | null;
60	  /** J/K availability; undefined hides the previous/next chevrons. */
61	  canMovePrev?: boolean;
62	  canMoveNext?: boolean;
63	}>();
64	
65	const emit = defineEmits<{
66	  close: [];
67	  /** Previous (-1) / next (+1) conversation, same path as K / J. */
68	  move: [delta: number];
69	  attachments: [origin: HTMLElement];
70	  archive: [];
71	  unarchive: [];
72	  setRead: [read: boolean];
73	  prepareReply: [source: DraftSource];
74	  /** Identity of the message that currently owns reader focus. */
75	  activeMessage: [messageId: string | null];
76	  /** Hover/focus participant context override; `null` restores the baseline. */
77	  contactOverride: [
78	    override:
79	      | { ref: ConversationRef; messageId: string; displayName: string | null; mailbox: string }
80	      | null,
81	  ];
82	}>();
83	
84	const container = ref<HTMLElement | null>(null);
85	const scrollerEl = ref<HTMLElement | null>(null);
86	const messageEls = new Map<string, HTMLElement>();
87	
88	/** Selected-scope toolbar mode: nonzero selection dispatches to the whole
89	 * selection with explicit count labels (§3.3); null keeps single behavior. */
90	const bulkScope = computed(() =>
91	  (props.selectionCount ?? 0) > 0
92	    ? { count: props.selectionCount!, context: props.selectionContext ?? 'inbox' }
93	    : null,
94	);
95	
96	type StarCoverage = NonNullable<Conversation['stars']>;
97	
98	/** Short visible star line; exact coverage moves to the title/description. */
99	function starSummary(stars: StarCoverage): string {
100	  if (stars.starredMessages > 0) return stars.knownMessages < stars.totalMessages ? 'Starred (partial)' : 'Starred';
101	  return stars.knownMessages === stars.totalMessages && stars.totalMessages > 0 ? 'Not starred' : 'Star state unknown';
102	}
103	
104	/** The line appears only with news: starred, incomplete coverage, or a pending
105	 * action (the effective value may then include unconfirmed intent). */
106	function starLine(conversation: NonNullable<typeof props.conversation>): { text: string; attention: boolean } | null {
107	  const stars = conversation.stars;
108	  if (!stars) return null;
109	  const complete = stars.totalMessages > 0 && stars.knownMessages === stars.totalMessages;
110	  const pending = Boolean(conversation.pendingOperationId);
111	  if (stars.starredMessages === 0 && complete && !pending) return null;
112	  return { text: starSummary(stars) + (pending ? ' (unconfirmed)' : ''), attention: !complete || pending };
113	}
114	
115	function starCoverageDetail(stars: StarCoverage): string {
116	  return `Effective star values known for ${stars.knownMessages} of ${stars.totalMessages} cached messages. Pending intent is not provider confirmation.`;
117	}
118	
119	const latestMessage = computed(() => props.conversation?.messages.at(-1) ?? null);
120	const replyBlockedReason = computed(() => {
121	  if (!props.conversation || !latestMessage.value) return 'No displayed latest message is available as a reply source.';
122	  if (props.conversation.retainedSnapshotAt) return 'Reply preparation is blocked for a retained snapshot; current message headers cannot be verified.';
123	  if (props.conversation.contextComplete === false) return 'Reply preparation is blocked because this cached conversation is incomplete.';
124	  if (props.conversation.replyContext && props.conversation.replyContext.sourceMessageId !== latestMessage.value.id) return 'Reply preparation is blocked because cached reply headers do not match the displayed latest message.';
125	  return null;
126	});
127	
128	const replySourceId = `reader-reply-source-${useId()}`;
129	const replyTargetLabel = computed(() => latestMessage.value
130	  ? `Reply targets the latest message from ${latestMessage.value.from.displayName ?? latestMessage.value.from.mailbox}`
131	  : '');
132	/** Conversation-specific actions exist only for a ready conversation. */
133	const actionable = computed(() => props.state === 'ready' && !!props.conversation);
134	/**
135	 * A previous conversation kept on screen while the J/K target loads. It is
136	 * display only: nothing in it is actionable as if it were the open thread.
137	 */
138	const held = computed(() => props.state === 'loading' && !!props.conversation && keyOfDisplayed() === null);
139	/** Header actions stay mounted (disabled, not removed) for as long as a conversation is open. */
140	const actionsShown = computed(() => props.openRef !== null || actionable.value);
141	const hasMetaRow = computed(() => {
142	  if (!(actionable.value || held.value)) return false;
143	  return !!(props.readOnly || props.showReadControls || bulkScope.value);
144	});
145	
146	function prepareReply(): void {
147	  // Reply always targets the explicitly displayed latest message; focusing an
148	  // older message never changes the reply contract.
149	  const conversation = props.conversation;
150	  const source = latestMessage.value;
151	  if (!conversation || !source || replyBlockedReason.value) return;
152	  emit('prepareReply', {
153	    kind: 'reply',
154	    conversation: { ...conversation.ref },
155	    sourceMessageId: source.id,
156	  });
157	}
158	
159	function describeError(error: MailError): string {
160	  switch (error.kind) {
161	    case 'not_found':
162	      return 'That conversation is no longer available.';
163	    case 'invalid_request':
164	      return `The request was rejected (invalid field: ${error.field}).`;
165	    case 'request_id_conflict':
166	      return 'The request conflicted with an earlier request ID.';
167	    case 'storage_unavailable':
168	      return 'Local storage is unavailable. The operation was not confirmed.';
169	    case 'profile_in_use':
170	      return 'Another window is using this profile.';
171	    case 'read_only':
172	      return 'Gmail is read-only; archiving is unavailable.';
173	    case 'not_configured':
174	      return 'Gmail is not configured on this device.';
175	    case 'auth_required':
176	      return 'Sign-in is required; cached conversations stay readable.';
177	    case 'auth_cancelled':
178	      return 'Sign-in was cancelled.';
179	    case 'auth_failed':
180	      return 'Sign-in failed. Cached conversations stay readable.';
181	    case 'secrets_unavailable':
182	      return 'Secure credential storage is unavailable.';
183	    case 'network_unavailable':
184	      return 'The network is unavailable; cached conversations stay readable.';
185	    case 'rate_limited':
186	      return 'The provider is rate limiting. Cached conversations stay readable.';
187	    case 'provider_unavailable':
188	      return 'The mail provider is temporarily unavailable.';
189	    case 'invalid_provider_response':
190	      return 'The provider returned an unexpected response.';
191	    case 'busy':
192	      return 'A sync is already in progress. Try again shortly.';
193	    case 'permission_required':
194	      return 'Google mailbox-action permission is not enabled.';
195	    case 'provider_rejected':
196	      return 'The provider rejected this action.';
197	    case 'outcome_unknown':
198	      return 'The remote result is uncertain. Review Activity before retrying.';
199	    default:
200	      return 'Could not load the conversation.';
201	  }
202	}
203	
204	// ---------------------------------------------------------------------------
205	// Visit-scoped message state, keyed by account+conversation
206	// ---------------------------------------------------------------------------
207	
208	/** Viewport-relative scroll anchor: a message top plus a scrollTop fallback. */
209	interface MessageAnchor { messageId: string; offsetTop: number; scrollTop: number }
210	
211	interface VisitState {
212	  activeMessageId: string | null;
213	  expandedIds: Set<string>;
214	  detailsOpenId: string | null;
215	  anchor: MessageAnchor | null;
216	  /** Message ordering this state was built against (for removed-ID resolution). */
217	  order: string[];
218	}
219	
220	const visits = new Map<string, VisitState>();
221	/** Reactive holder for the currently displayed visit. */
222	const visitRef = ref<VisitState | null>(null);
223	let lastDataKey: string | null = null;
224	/**
225	 * Foreground activation intent, tracked separately from `lastDataKey`: a
226	 * loading transition that removed reader-owned focus owes the next ready
227	 * snapshot a message-focus restoration, even when the user reverses back to
228	 * the same key as the last loaded one (which would otherwise be classified as
229	 * an unfocused same-reference background replacement).
230	 */
231	let pendingFocusRestore = false;
232	
233	function visitKey(ref: ConversationRef): string {
234	  return `${ref.accountId}:${ref.conversationId}`;
235	}
236	
237	function keyOfDisplayed(): string | null {
238	  const conversation = props.conversation;
239	  const open = props.openRef;
240	  if (!conversation || !open) return null;
241	  if (conversation.ref.accountId !== open.accountId || conversation.ref.conversationId !== open.conversationId) return null;
242	  return visitKey(conversation.ref);
243	}
244	
245	/**
246	 * Prune removed message IDs and resolve removed active/anchor IDs by the
247	 * surviving old neighbors (next surviving old neighbor, then previous), so a
248	 * background replacement can never leave a stale message target.
249	 */
250	function pruneVisit(visit: VisitState, nextIds: string[]): void {
251	  const present = new Set(nextIds);
252	  const resolve = (id: string | null): string | null => {
253	    if (id === null || present.has(id)) return id;
254	    const oldIndex = visit.order.indexOf(id);
255	    if (oldIndex >= 0) {
256	      for (let i = oldIndex + 1; i < visit.order.length; i += 1) {
257	        const candidate = visit.order[i]!;
258	        if (present.has(candidate)) return candidate;
259	      }
260	      for (let i = oldIndex - 1; i >= 0; i -= 1) {
261	        const candidate = visit.order[i]!;
262	        if (present.has(candidate)) return candidate;
263	      }
264	    }
265	    return null;
266	  };
267	  visit.activeMessageId = resolve(visit.activeMessageId);
268	  visit.detailsOpenId = visit.detailsOpenId !== null && present.has(visit.detailsOpenId) ? visit.detailsOpenId : null;
269	  if (visit.anchor && !present.has(visit.anchor.messageId)) {
270	    const resolved = resolve(visit.anchor.messageId);
271	    visit.anchor = resolved
272	      ? { ...visit.anchor, messageId: resolved }
273	      : { messageId: '', offsetTop: 0, scrollTop: visit.anchor.scrollTop };
274	  }
275	  visit.expandedIds = new Set([...visit.expandedIds].filter((id) => present.has(id)));
276	  visit.order = [...nextIds];
277	}
278	
279	function captureScrollAnchor(visit: VisitState): MessageAnchor | null {
280	  const scroller = scrollerEl.value;
281	  if (!scroller || visit.order.length === 0) return null;
282	  const scrollerTop = scroller.getBoundingClientRect().top;
283	  for (const id of visit.order) {
284	    const el = messageEls.get(id);
285	    if (!el) continue;
286	    const top = el.getBoundingClientRect().top;
287	    if (top >= scrollerTop - 1 || id === visit.order[visit.order.length - 1]) {
288	      return { messageId: id, offsetTop: top - scrollerTop, scrollTop: scroller.scrollTop };
289	    }
290	  }
291	  return null;
292	}
293	
294	function restoreScroll(visit: VisitState, scroller: HTMLElement): void {
295	  const anchor = visit.anchor;
296	  if (!anchor) return;
297	  const el = messageEls.get(anchor.messageId);
298	  if (!el || scroller.clientHeight === 0 || !anchor.messageId) {
299	    // Fallback: the anchored message no longer exists; restore the raw offset.
300	    scroller.scrollTop = anchor.scrollTop;
301	    return;
302	  }
303	  const relative = el.getBoundingClientRect().top - scroller.getBoundingClientRect().top;
304	  scroller.scrollTop = scroller.scrollTop + (relative - anchor.offsetTop);
305	}
306	
307	function focusElement(el: HTMLElement | null | undefined, reveal: boolean): boolean {
308	  if (!el || !el.isConnected) return false;
309	  // Never move focus into an inert ancestor (e.g. a drawer covering the reader).
310	  if (el.closest('[inert]')) return false;
311	  el.focus({ preventScroll: true });
312	  if (reveal && typeof el.scrollIntoView === 'function') el.scrollIntoView({ block: 'nearest' });
313	  return document.activeElement === el;
314	}
315	
316	function focusMessageToggle(messageId: string, reveal: boolean): void {
317	  focusElement(messageEls.get(messageId)?.querySelector<HTMLElement>('.message-toggle'), reveal);
318	}
319	
320	type ComponentPublicInstance = import('vue').ComponentPublicInstance;
321	
322	function setMessageEl(el: Element | ComponentPublicInstance | null, messageId: string): void {
323	  if (el instanceof HTMLElement) messageEls.set(messageId, el);
324	  else messageEls.delete(messageId);
325	}
326	
327	let updateSeq = 0;
328	
329	/**
330	 * Loading teardown: if reader-owned focus was dropped to <body> because the
331	 * loading placeholder removed the focused message control, park it on the
332	 * persistent reader article. Never steals toolbar, rail, overlay, or other
333	 * unrelated focus — including a surface the user moved to while this delayed
334	 * work was in flight — respects inert ancestors, and is invalidated by any
335	 * newer update (a ready snapshot takes over via schedulePostUpdate).
336	 */
337	async function scheduleLoadingFocus(seq: number): Promise<void> {
338	  await nextTick();
339	  if (seq !== updateSeq) return;
340	  // Focus already lives on a surviving reader surface (e.g. the toolbar);
341	  // leave it exactly where it is.
342	  if (container.value?.contains(document.activeElement) ?? false) return;
343	  // Park only over focus that fell to <body> when the message control was
344	  // torn down: a still-focused rail/outside button keeps its focus.
345	  const active = document.activeElement;
346	  if (active !== null && active !== document.body) return;
347	  focusElement(container.value, false);
348	}
349	
350	/**
351	 * Post-update work for one conversation snapshot: restore the visit's scroll
352	 * position and, on a visit switch, focus the visit's active message toggle
353	 * (the article stays the empty/error fallback). The delayed focus is guarded
354	 * against a changed reference, a newer update, and inert ancestors.
355	 */
356	async function schedulePostUpdate(key: string, focusIntent: boolean, readerHadFocus: boolean, restoringAfterLoading: boolean, switched: boolean): Promise<void> {
357	  const seq = ++updateSeq;
358	  await nextTick();
359	  if (seq !== updateSeq || keyOfDisplayed() !== key) return;
360	  const visit = visits.get(key);
361	  const scroller = scrollerEl.value;
362	  if (visit && scroller) {
363	    // A returning visit restores its anchor; a first visit starts at the top
364	    // instead of inheriting the outgoing conversation's offset.
365	    if (visit.anchor) restoreScroll(visit, scroller);
366	    else if (switched) scroller.scrollTop = 0;
367	  }
368	  const messages = props.conversation?.messages ?? [];
369	  // A replacement that removed the focused message element must not drop
370	  // reader focus to <body>; resolve it to the visit's active message toggle.
371	  if (!focusIntent && readerHadFocus && !(container.value?.contains(document.activeElement) ?? false)) {
372	    if (messages.length === 0 || !visit?.activeMessageId) {
373	      focusElement(container.value, false);
374	      return;
375	    }
376	    // Scroll geometry was just restored; do not let focus-reveal shift it.
377	    focusMessageToggle(visit.activeMessageId, false);
378	    return;
379	  }
380	  if (!focusIntent) return;
381	  if (restoringAfterLoading) {
382	    // A delayed reversal must not yank focus from a surface the user moved to
383	    // while the loading placeholder was up: only our own parked article focus
384	    // (or focus that fell to <body>) may be promoted to a restoration target.
385	    // This ownership check must come BEFORE choosing the target so it also
386	    // protects the empty-visit article fallback, not just the message toggle.
387	    const active = document.activeElement;
388	    const inReader = active instanceof Node && (container.value?.contains(active) ?? false);
389	    if (inReader ? active !== container.value : active !== null && active !== document.body) return;
390	  }
391	  if (messages.length === 0 || !visit?.activeMessageId) {
392	    // Empty/error fallback: the reader article keeps focus instead of a
393	    // message control that does not exist.
394	    focusElement(container.value, false);
395	    return;
396	  }
397	  // A revisit with a saved anchor is positioned by restoreScroll; focusing
398	  // must not reveal-scroll and destroy the restored reading offset. A first
399	  // visit has no geometry yet, so reveal the focused header as needed.
400	  focusMessageToggle(visit.activeMessageId, visit.anchor === null);
401	}
402	
403	watch(
404	  () => props.conversation,
405	  (conversation) => {
406	    // Capture the outgoing visit's scroll geometry BEFORE any DOM teardown,
407	    // including the foreground null/loading transition: useMailbox clears the
408	    // conversation before the next detail arrives, and by the following
409	    // non-null update the outgoing message elements are already gone. This
410	    // watcher runs pre-flush, so the old elements are still live here. The
411	    // capture is a no-op once the elements are gone, so a loading/empty DOM
412	    // can never overwrite a saved anchor.
413	    const outgoing = lastDataKey !== null ? visits.get(lastDataKey) : null;
414	    if (outgoing && scrollerEl.value) {
415	      const captured = captureScrollAnchor(outgoing);
416	      if (captured) outgoing.anchor = captured;
417	    }
418	    const readerHadFocus = container.value?.contains(document.activeElement) ?? false;
419	    if (!conversation) {
420	      // Loading/error: visit state must not be erased. Only reader-owned
421	      // focus that is about to lose its message control is parked on the
422	      // persistent reader article (not <body>) and remembered for message
423	      // focus restoration on the next ready snapshot even when it resolves to
424	      // the last loaded key (immediate reversal). Focus that already lives
425	      // elsewhere (rail/overlay/outside) is never scheduled over.
426	      const seq = ++updateSeq;
427	      if (readerHadFocus) {
428	        pendingFocusRestore = true;
429	        void scheduleLoadingFocus(seq);
430	      }
431	      return;
432	    }
433	    const key = visitKey(conversation.ref);
434	    const previousKey = lastDataKey;
435	    const ids = conversation.messages.map((message) => message.id);
436	    let visit = visits.get(key);
437	    if (!visit) {
438	      const newest = ids[ids.length - 1] ?? null;
439	      // Reactive so state mutations (pruning resolution, command handlers)
440	      // publish through visitRef to templates and the active-ID watcher.
441	      visit = reactive<VisitState>({
442	        activeMessageId: newest,
443	        expandedIds: new Set(newest === null ? [] : [newest]),
444	        detailsOpenId: null,
445	        anchor: null,
446	        order: [...ids],
447	      });
448	      visits.set(key, visit);
449	    } else {
450	      pruneVisit(visit, ids);
451	    }
452	    visitRef.value = visit;
453	    lastDataKey = key;
454	    // Foreground activation is tracked separately from the last loaded key:
455	    // a reversal back to the same key still owes a focus restoration.
456	    const restoringAfterLoading = pendingFocusRestore;
457	    pendingFocusRestore = false;
458	    // A same-reference replacement never changes focus; a visit switch or a
459	    // reversed loading transition does.
460	    void schedulePostUpdate(key, key !== previousKey || restoringAfterLoading, readerHadFocus, restoringAfterLoading, key !== previousKey);
461	  },
462	  { immediate: true, flush: 'pre' },
463	);
464	
465	/** Loading/error fallback: keep the reader article focused, never steal toolbar focus. */
466	watch(
467	  () => props.state,
468	  async (state) => {
469	    if (state !== 'error') return;
470	    const seq = ++updateSeq;
471	    await nextTick();
472	    if (seq !== updateSeq) return;
473	    const active = document.activeElement;
474	    if (active instanceof Node && container.value?.contains(active)) return;
475	    focusElement(container.value, false);
476	  },
477	);
478	
479	// Reader focus identity + participant context (App consumes these).
480	watch(
481	  () => visitRef.value?.activeMessageId ?? null,
482	  (activeId) => { emit('activeMessage', activeId); },
483	  { immediate: true },
484	);
485	
486	const hoverParticipant = ref<{ messageId: string; address: Address } | null>(null);
487	const focusParticipant = ref<{ messageId: string; address: Address } | null>(null);
488	// Keyboard focus overrides hover independently; both restore the baseline on exit.
489	const effectiveParticipant = computed(() => focusParticipant.value ?? hoverParticipant.value);
490	
491	watch(
492	  effectiveParticipant,
493	  (value) => {
494	    const open = props.openRef;
495	    if (!value || !open) {
496	      emit('contactOverride', null);
497	      return;
498	    }
499	    emit('contactOverride', {
500	      ref: { ...open },
501	      messageId: value.messageId,
502	      displayName: value.address.displayName,
503	      mailbox: value.address.mailbox,
504	    });
505	  },
506	);
507	
508	function sameParticipant(
509	  current: { messageId: string; address: Address } | null,
510	  messageId: string,
511	  address: Address,
512	): boolean {
513	  return current !== null && current.messageId === messageId && current.address.mailbox === address.mailbox;
514	}
515	
516	function onParticipantEnter(message: Message, address: Address): void {
517	  hoverParticipant.value = { messageId: message.id, address };
518	}
519	
520	function onParticipantLeave(message: Message, address: Address): void {
521	  if (sameParticipant(hoverParticipant.value, message.id, address)) hoverParticipant.value = null;
522	}
523	
524	function onParticipantFocus(message: Message, address: Address): void {
525	  focusParticipant.value = { messageId: message.id, address };
526	}
527	
528	function onParticipantBlur(message: Message, address: Address): void {
529	  if (sameParticipant(focusParticipant.value, message.id, address)) focusParticipant.value = null;
530	}
531	
532	// ---------------------------------------------------------------------------
533	// Message rendering helpers + narrow message commands (exposed to App)
534	// ---------------------------------------------------------------------------
535	
536	/**
537	 * The visit a message command may act on: only a ready, matching displayed
538	 * reference qualifies. During loading the outgoing visit stays saved for
539	 * restoration, but stale commands must never mutate it.
540	 */
541	function displayedVisit(): VisitState | null {
542	  if (props.state !== 'ready') return null;
543	  const key = keyOfDisplayed();
544	  return key !== null ? visits.get(key) ?? null : null;
545	}
546	
547	function isActive(message: Message): boolean {
548	  return visitRef.value?.activeMessageId === message.id;
549	}
550	
551	/** Roving tabindex: the active toggle is the tab stop; the first is the fallback. */
552	function tabIndexFor(message: Message): 0 | -1 {
553	  if (isActive(message)) return 0;
554	  if ((visitRef.value?.activeMessageId ?? null) === null && message.id === (props.conversation?.messages[0]?.id ?? null)) return 0;
555	  return -1;
556	}
557	
558	function isExpanded(message: Message): boolean {
559	  return visitRef.value?.expandedIds.has(message.id) ?? false;
560	}
561	
562	function isDetailsOpen(message: Message): boolean {
563	  return visitRef.value?.detailsOpenId === message.id;
564	}
565	
566	function bodyId(message: Message): string {
567	  return `reader-body-${props.conversation?.ref.accountId}-${message.id}`.replace(/[^A-Za-z0-9_-]/g, '-');
568	}
569	
570	function setActive(messageId: string): void {
571	  const visit = visitRef.value;
572	  if (visit && visit.activeMessageId !== messageId) visit.activeMessageId = messageId;
573	}
574	
575	function setActiveByFocus(message: Message): void {
576	  // Focusing any control of a message updates its message identity.
577	  setActive(message.id);
578	}
579	
580	/** Collapsing a message also closes its details: collapsed messages show no Details UI. */
581	function collapseMessage(visit: VisitState, id: string): void {
582	  visit.expandedIds.delete(id);
583	  if (visit.detailsOpenId === id) visit.detailsOpenId = null;
584	  if (focusParticipant.value?.messageId === id) focusParticipant.value = null;
585	  if (hoverParticipant.value?.messageId === id) hoverParticipant.value = null;
586	}
587	
588	function toggleMessage(message: Message): void {
589	  const visit = visitRef.value;
590	  if (!visit || !actionable.value) return;
591	  setActive(message.id);
592	  if (visit.expandedIds.has(message.id)) collapseMessage(visit, message.id);
593	  else visit.expandedIds.add(message.id);
594	}
595	
596	function onDetailsToggle(event: Event, message: Message): void {
597	  const visit = visitRef.value;
598	  if (!visit) return;
599	  if (!actionable.value) {
600	    // Held content: keep the disclosure exactly as saved.
601	    (event.target as HTMLDetailsElement).open = isDetailsOpen(message);
602	    return;
603	  }
604	  const open = (event.target as HTMLDetailsElement).open;
605	  if (open && visit.detailsOpenId !== message.id) visit.detailsOpenId = message.id;
606	  else if (!open && visit.detailsOpenId === message.id) {
607	    visit.detailsOpenId = null;
608	    // Dismissing the disclosure ends its participant context: a browser may
609	    // keep focus inside the closed disclosure without firing blur, so clear
610	    // the keyboard-held override for this message explicitly.
611	    if (focusParticipant.value?.messageId === message.id) focusParticipant.value = null;
612	    if (hoverParticipant.value?.messageId === message.id) hoverParticipant.value = null;
613	  }
614	}
615	
616	/** N/P: move message focus without implicitly expanding (no wrap). */
617	function moveMessage(delta: number): void {
618	  const visit = displayedVisit();
619	  const messages = props.conversation?.messages ?? [];
620	  if (!visit || messages.length === 0) return;
621	  const ids = messages.map((message) => message.id);
622	  const index = visit.activeMessageId ? ids.indexOf(visit.activeMessageId) : -1;
623	  const targetIndex = index < 0
624	    ? (delta > 0 ? 0 : ids.length - 1)
625	    : Math.min(ids.length - 1, Math.max(0, index + delta));
626	  const target = messages[targetIndex]!;
627	  setActive(target.id);
628	  // Explicit movement reveals the target header as needed.
629	  focusMessageToggle(target.id, true);
630	}
631	
632	/** O: expand/collapse the focused message. */
633	function toggleActiveMessage(): void {
634	  const visit = displayedVisit();
635	  if (!visit || !visit.activeMessageId) return;
636	  if (visit.expandedIds.has(visit.activeMessageId)) collapseMessage(visit, visit.activeMessageId);
637	  else visit.expandedIds.add(visit.activeMessageId);
638	  focusMessageToggle(visit.activeMessageId, true);
639	}
640	
641	/** Shift+O: idempotent expand-all. */
642	function expandAllMessages(): void {
643	  const visit = displayedVisit();
644	  const messages = props.conversation?.messages ?? [];
645	  if (!visit || messages.length === 0) return;
646	  for (const message of messages) visit.expandedIds.add(message.id);
647	}
648	
649	function hasOpenDetails(): boolean {
650	  const visit = displayedVisit();
651	  return visit?.detailsOpenId !== null && visit?.detailsOpenId !== undefined;
652	}
653	
654	/** Escape dismissal of an open message-details disclosure. Returns true when one was open. */
655	function dismissMessageDetails(): boolean {
656	  const visit = displayedVisit();
657	  if (!visit || visit.detailsOpenId === null) return false;
658	  const id = visit.detailsOpenId;
659	  visit.detailsOpenId = null;
660	  focusMessageToggle(id, true);
661	  return true;
662	}
663	
664	defineExpose({
665	  moveMessage,
666	  toggleActiveMessage,
667	  expandAllMessages,
668	  hasOpenDetails,
669	  dismissMessageDetails,
670	});
