2	/**
3	 * Plain-text, keyboard-first conversation reader (UX-02). Opening is read-only —
4	 * never marks read.
5	 *
6	 * Visit-scoped message state (active message, expansion, details disclosure,
7	 * scroll anchor) lives inside this mounted reader instance, keyed by
8	 * account+conversation reference and message ID — never by array position. It
9	 * survives J/K round trips and same-reference background replacements within
10	 * the reader session and is released when the reader closes (component
11	 * unmount) or the account changes.
12	 *
13	 * Archive/read controls are shown only when the authoritative capability permits them, and
14	 * Gmail-supplied plain-text limitations are disclosed explicitly (`unsupportedReason`,
15	 * `contextComplete === false`) instead of silently dropping content.
16	 *
17	 * Safety: message content is rendered exclusively through text interpolation
18	 * ({{ }}). No v-html, no markdown/HTML processing, no remote assets anywhere in
19	 * this slice — hostile markup stays literal text. Reply preparation always
20	 * targets the explicitly displayed latest message, never the focused message.
21	 *
22	 * Message commands (N/P/O/Shift+O, details dismissal) are exposed as narrow
23	 * methods for App's single keyboard dispatcher — this component never adds its
24	 * own window listener.
25	 */
26	import { actionLabel } from '../lib/browsing-actions';
27	import { compactDateLabel, fullDateLabel, machineDateTime } from '../lib/browsing-dates';
28	import { messageSnippet } from '../lib/message-snippet';
29	import { bodyNeedsMonospace } from '../lib/message-body-format';
30	import { computed, nextTick, reactive, ref, useId, watch } from 'vue';
31	import HeaderGlyph from './HeaderGlyph.vue';
32	import type { Address, Conversation, ConversationRef, DraftSource, MailError, Message } from '../lib/ipc/client';
33	import type { DetailState } from '../composables/useMailbox';
34	
35	const props = defineProps<{
36	  conversation: Conversation | null;
37	  state: DetailState;
38	  error: MailError | null;
39	  commandInFlight: boolean;
40	  /** The conversation reference the shell currently wants displayed. */
41	  openRef: ConversationRef | null;
42	  /**
43	   * Target identity from the list's own row, shown while the target loads and
44	   * no previous conversation is held. Never message content.
45	   */
46	  loadingIdentity?: { subject: string; sender: string | null; at: string | null } | null;
47	  /** Gmail mode: archive/unarchive controls are hidden, not just disabled. */
48	  readOnly?: boolean;
49	  browsingOnly?: boolean;
50	  navigationUnavailable?: boolean;
51	  showReadControls?: boolean;
52	  /** Nonzero: shared controls dispatch to the SELECTION (§3.3), so the reader
53	   * offers explicit count-labelled desired-state controls instead of the open
54	   * conversation's single-state toggles (mixed selections included). */
55	  selectionCount?: number;
56	  selectionContext?: 'inbox' | 'saved' | 'done' | 'starred' | 'search';
57	  /** Header slots the quiet icon actions are teleported into; inline when null. */
58	  backHost?: HTMLElement | null;
59	  actionsHost?: HTMLElement | null;
60	  /** J/K availability; undefined hides the previous/next chevrons. */
61	  canMovePrev?: boolean;
62	  canMoveNext?: boolean;
63	}>();
64	
65	const emit = defineEmits<{
66	  close: [];
67	  /** Previous (-1) / next (+1) conversation, same path as K / J. */
68	  move: [delta: number];
69	  attachments: [origin: HTMLElement];
70	  archive: [];
71	  unarchive: [];
72	  setRead: [read: boolean];
73	  prepareReply: [source: DraftSource];
74	  /** Identity of the message that currently owns reader focus. */
75	  activeMessage: [messageId: string | null];
76	  /** Hover/focus participant context override; `null` restores the baseline. */
77	  contactOverride: [
78	    override:
79	      | { ref: ConversationRef; messageId: string; displayName: string | null; mailbox: string }
80	      | null,
81	  ];
82	}>();
83	
84	const container = ref<HTMLElement | null>(null);
85	const scrollerEl = ref<HTMLElement | null>(null);
86	const messageEls = new Map<string, HTMLElement>();
87	
88	/** Selected-scope toolbar mode: nonzero selection dispatches to the whole
89	 * selection with explicit count labels (§3.3); null keeps single behavior. */
90	const bulkScope = computed(() =>
91	  (props.selectionCount ?? 0) > 0
92	    ? { count: props.selectionCount!, context: props.selectionContext ?? 'inbox' }
93	    : null,
94	);
95	
96	type StarCoverage = NonNullable<Conversation['stars']>;
97	
98	/** Short visible star line; exact coverage moves to the title/description. */
99	function starSummary(stars: StarCoverage): string {
100	  if (stars.starredMessages > 0) return stars.knownMessages < stars.totalMessages ? 'Starred (partial)' : 'Starred';
101	  return stars.knownMessages === stars.totalMessages && stars.totalMessages > 0 ? 'Not starred' : 'Star state unknown';
102	}
103	
