130:## Reconstruction choices (marked, not verified Superhuman fidelity)

.reader-pane,
.reader {
  min-height: 0;
  min-width: 0;
}

.reader-pane {
  display: flex;
  flex-direction: column;
  padding: 0.5rem 0.75rem;
}

.reader {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.reader:focus {
  outline: none;
}

/* Quiet icon actions teleported into the app header: the hosts take no box of
   their own so the glyphs sit on the header's 32px pitch. Standalone (no
   host) they flow inline. */
.reader-back-host,
.reader-actions-host {
  display: contents;
}

.reader-actions {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
}

/* Back arrow leads the context title; its glyph sits on the 50px inset. */
.header-tabs > .reader-back-host > .reader-back {
  align-self: center;
  margin-left: -8px;
  margin-right: -10px;
}

.header-tabs:has(> .reader-back-host > .reader-back) {
  align-items: center;
}

/* Honest-state text controls under the subject: one quiet line, only when present. */
.reader-meta-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 12px;
  color: var(--text-secondary);
}

.reader-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

/* Headline at the strong weight: the subject leads the reader without a third size. */
.reader-subject {
  font-size: var(--type-headline);
  font-weight: var(--weight-strong);
  line-height: var(--leading-headline);
  overflow-wrap: anywhere;
}

/* Loading identity: the list row's sender and date under the subject, then one
   quiet line. No motion; same type scale as the loaded reader. */
.reader-loading-identity {
  display: flex;
  gap: 12px;
  margin: 0.2rem 0;
  color: var(--text-secondary);
}

.reader-loading-quiet {
  color: var(--text-secondary);
}

.reader-context-note {
  max-width: 80ch;
  margin: 0.2rem 0;
  color: var(--text-secondary);
  font-size: var(--type-body);
}

/* Partial, unknown and unconfirmed star state read as Amber Notice. */
.reader-context-note[data-attention] {
  color: var(--warning);
}

.reader-pending {
  font-style: italic;
}

.messages {
  list-style: none;
  padding: 0;
  margin: 0;
}

.message {
  position: relative;
  border-top: 1px solid var(--rule);
  padding: 0.4rem 0.4rem 0.6rem;
  margin-bottom: 0.5rem;
}

/*
 * Current-message treatment: an accent-purple bar (color) plus a non-color
 * indication (a flat raised fill and a primary-color sender) so the focused
 * message never relies on color alone.
 */
.message.message-active {
  background: var(--surface-raised);
  box-shadow: inset 3px 0 0 var(--focus-accent);
}

/* The active bar is the focus indicator for the message toggle: no second ring.
   The fill, bold sender and bar remain; other controls keep the global ring. */
.message.message-active .message-toggle:focus-visible {
  outline: none;
}

.message-toggle {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex: 1;
  min-width: 0;
  min-height: 2em;
  text-align: left;
  font-size: var(--type-body);
  color: var(--text-secondary);
  background: transparent;
  border: 0;
  padding: 0.1rem 0.2rem;
}

.message-from,
.message-to {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Collapsed senders share one 132px column so the snippets line up. */
.message-toggle[aria-expanded='false'] .message-from {
  flex: 0 0 11em;
}

.message-toggle[aria-expanded='false'] .message-to {
  display: none;
}

.message-snippet {
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.message-time {
  flex: none;
  margin-left: auto;
  text-align: right;
  text-transform: uppercase;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/*
 * Prose reads in the proportional face at the reading size. 65ch (width of "0")
 * is about 90 average proportional characters per line, short enough to follow.
 * Bodies that rely on column alignment (quotes, indented blocks, tables) keep
 * the raw monospace.
 */
.message-body {
  white-space: pre-wrap;
  font-family: var(--font-ui);
  font-size: var(--type-reading);
  line-height: var(--leading-reading);
  max-width: 65ch;
  color: var(--text-primary);
  overflow-wrap: anywhere;
  margin: 0.4rem 0;
}

.message-body.message-body-mono {
  font-family: var(--font-mono);
  font-size: var(--type-mono);
  line-height: var(--leading-mono);
  /* Hard-wrapped plain text is 72-78 columns; do not soft-wrap it a second time. */
  max-width: 88ch;
}

/* Per-message participant details disclosure (native details/summary). Only
   rendered visible inside an expanded message: the summary is a quiet line
   under the header (in flow, so it can never collide with the date or the reply
   glyph); the fields open below it. */
.message-details {
.drafts-pane {
  display: grid;
  grid-template-columns: minmax(190px, 0.7fr) minmax(0, 2fr);
  gap: 0.8rem;
  min-height: 0;
}

.draft-list,
.composer {
  min-width: 0;
}

.draft-list-heading,
.composer-heading,
.composer-actions,
.conflict-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.draft-list-heading h2,
.composer-heading h2 {
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
  margin: 0.25rem 0;
  overflow-wrap: anywhere;
}

/* Informational note: secondary text, not a warning. Warnings stay on
   status/error lines (draft-status, reply-source). */
.draft-local-note {
  margin: 0.3rem 0;
  font-size: var(--type-body);
  color: var(--text-secondary);
}

.reply-source,
.draft-status {
  margin: 0.3rem 0;
  font-size: var(--type-body);
  color: var(--warning);
}

/* Shared composer body (DraftEditorCore) inside any surface. */
.composer-body {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
}

/* "Draft" state flag: plain strong text, never uppercase/tracked and never a
   second accent — the reader's active-message bar already owns focus-accent. */
.draft-flag {
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

